/**
 * 负责定序王子原状态读取、初始构造、脱离历史投影与下一选择数据准备。
 * 输入为原角色、观察／选择日和 activate；输出为原槽同引用或独立可写数据，不提交效果。
 * 公共字段结构归 GC facts/order-prince；本 owner 保持原精确描述符／Proxy 拒绝与历史顺序，
 * 真实 pending、原生命和写权仍由 authority 持有，准备副本不授予重投权限。
 */
import type { OrderPrinceChoice, OrderPrinceState } from "@ai-werewolf-arena/game-contract/facts/order-prince";
import { types } from "node:util";
import { Camp, type RoleComponent } from "../../../../core";

export const ORDER_PRINCE_ROLE = "order_prince" as const;
export const ORDER_PRINCE_POLICY = "awa_order_prince_first_ballot_v1" as const;
function field(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function exact(value: unknown, keys: readonly string[]): boolean {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === keys.length &&
    keys.every((key) => descriptors[key] && "value" in descriptors[key]!)
  );
}
function dayNumber(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
function rows(value: unknown): unknown[] | undefined {
  if (types.isProxy(value) || !Array.isArray(value)) return undefined;
  const length = field(value, "length");
  if (typeof length !== "number" || !Number.isSafeInteger(length) || length < 0) return undefined;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).length !== length + 1) return undefined;
  const result: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const d = descriptors[String(i)];
    if (!d || !("value" in d)) return undefined;
    result.push(d.value);
  }
  return result;
}
/** 按原 own data descriptor 检查原槽；Node Proxy 先拒绝，成功返回同一原状态引用。 */
export function getOrderPrinceState(role: RoleComponent | undefined): OrderPrinceState | undefined {
  if (field(role, "role") !== ORDER_PRINCE_ROLE || field(role, "camp") !== Camp.Good)
    return undefined;
  const state = field(field(role, "privateState"), "orderPrince");
  if (!exact(state, ["policy", "history"]) || field(state, "policy") !== ORDER_PRINCE_POLICY)
    return undefined;
  const history = rows(field(state, "history"));
  if (!history) return undefined;
  let previous = 0;
  let consumed = false;
  for (const row of history) {
    if (!exact(row, ["day", "activate"])) return undefined;
    const day = field(row, "day");
    const activate = field(row, "activate");
    if (!dayNumber(day) || day <= previous || typeof activate !== "boolean" || consumed)
      return undefined;
    previous = day;
    consumed = activate;
  }
  return state as OrderPrinceState;
}
export function createOrderPrinceState(): OrderPrinceState {
  return { policy: ORDER_PRINCE_POLICY, history: [] };
}
export function projectOrderPrinceState(
  role: RoleComponent | undefined,
): OrderPrinceState | undefined {
  const state = getOrderPrinceState(role);
  if (!state) return undefined;
  // 每行重新构造，保持原可写历史数组；调用者修改该知识不会改写原槽。
  const history: OrderPrinceChoice[] = [];
  for (const row of rows(field(state, "history"))!) {
    history.push({
      day: field(row, "day") as number,
      activate: field(row, "activate") as boolean,
    });
  }
  return { policy: ORDER_PRINCE_POLICY, history };
}
/** 准备独立下一状态；原 caller 重验 pending 与原生命后才提交，不写 live 槽。 */
export function nextOrderPrinceChoice(
  role: RoleComponent | undefined,
  day: number,
  activate: boolean,
): OrderPrinceState | undefined {
  const state = projectOrderPrinceState(role);
  if (!state || !dayNumber(day) || typeof activate !== "boolean") return undefined;
  const last = state.history.at(-1);
  if (last && (last.activate || last.day >= day)) return undefined;
  state.history.push({ day, activate });
  return state;
}

/**
 * 负责 定序王子 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Role, Camp, WinCondition, Phase } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { ORDER_PRINCE_POLICY, createOrderPrinceState, getOrderPrinceState } from "./state";
import { orderPrinceChoicePending } from "./authority";
const parameters = z.strictObject({
  policy: z.literal(ORDER_PRINCE_POLICY).default(ORDER_PRINCE_POLICY),
});
export const ORDER_PRINCE_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.OrderPrince,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterSide],
    supportedBoardRoles: [
      Role.TimeWolfConsort,
      Role.Guard,
      Role.Trickster,
      Role.Magician,
      Role.Wolf,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.OrderPrince,
    ],
    label: roleName("order_prince"),
    skillBrief: text("zh-CN", "role.order_prince.brief"),
  },
  runtime: {
    init: (role) => {
      role.privateState.orderPrince = createOrderPrinceState();
    },
    configuration: {
      schema: parameters,
      defaults: parameters.parse({}),
      apply: (config, value) => ({ ...config, orderPrince: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.orderPrince ?? {}),
    },
    toolSpecs: [
      {
        name: "reset_exile_vote",
        parameters: {
          type: "object",
          properties: { activate: { type: "boolean" } },
          required: ["activate"],
          additionalProperties: false,
        },
        argHint: 'reset_exile_vote args: {"activate":true|false}',
        userPromptHintKey: "action.reset_exile_vote.hint",
      },
    ],
    stageDirectives: [
      {
        match: (tools) => tools.length === 1 && tools[0] === "reset_exile_vote",
        messageKey: "action.reset_exile_vote.directive",
        text: text("zh-CN", "action.reset_exile_vote.directive"),
      },
    ],
    validationRules: {
      reset_exile_vote: ({ world, role, actorId, day, phase, toolCall }) => {
        if (
          !getOrderPrinceState(role) ||
          day === undefined ||
          phase !== Phase.Voting ||
          toolCall.name !== "reset_exile_vote" ||
          !orderPrinceChoicePending(world, actorId, day)
        )
          return { code: RuleError.OrderPrinceUnavailable };
        return null;
      },
    },
    baselineAction: (role, request) =>
      request.allowedTools.includes("reset_exile_vote") && getOrderPrinceState(role)
        ? { name: "reset_exile_vote", args: { activate: true } }
        : null,
  },
  presentation: nativeRolePresentation("order_prince"),
};

/**
 * 负责定序王子的原身份／生命绑定与待答选择，拥有唯一 orderPrince 槽和 pending 的写权。
 * 输入为 World、原参与者与日次／activate，输出为当前性查询或已提交选择证据。
 * 不变量：只有匹配 pending 且原体／生命未撤权的选择可提交；关闭仅清 pending。
 * 写入依原槽、绑定引用、JSON 证据、pending 的顺序，失败保留已发生前缀，不缓存新容器
 * 或把公共状态数据当成许可。初始安装和纯数据投影不替代提交前复验。
 */
import type { OrderPrinceState } from "@ai-werewolf-arena/game-contract/facts/order-prince";
import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { aliveLifeDescriptor, aliveLifeVersion } from "../../../../core/domain/components/alive";
import type { World } from "../../../../core/domain/world";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import {
  getOrderPrinceState,
  projectOrderPrinceState,
  nextOrderPrinceChoice,
  ORDER_PRINCE_ROLE,
} from "./state";

interface Authority {
  actorId: number;
  role: RoleComponent;
  privateState: RoleComponent["privateState"];
  state: OrderPrinceState;
  expected: string;
  identity: unknown;
  identityValue: string;
  life: NightLifeScope;
  pendingDay: number | null;
}
const bindings = new WeakMap<World, Authority>();
function own(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function identityValue(value: unknown): string {
  const values = ["id", "seat", "name", "sessionId"].map((key) => own(value, key));
  if (
    !Number.isSafeInteger(values[0]) ||
    !Number.isSafeInteger(values[1]) ||
    typeof values[2] !== "string" ||
    typeof values[3] !== "string"
  )
    throw new Error("order_prince_identity_invalid");
  return JSON.stringify(values);
}
function requireAuthority(world: World): Authority {
  const b = bindings.get(world);
  if (!b) throw new Error("order_prince_board_missing");
  if (
    world.getComponent(b.actorId, COMPONENT.Role) !== b.role ||
    own(b.role, "privateState") !== b.privateState ||
    getOrderPrinceState(b.role) !== b.state ||
    JSON.stringify(projectOrderPrinceState(b.role)) !== b.expected ||
    world.getComponent(b.actorId, COMPONENT.Identity) !== b.identity ||
    identityValue(b.identity) !== b.identityValue
  )
    throw new Error("order_prince_original_state_revoked");
  const life = b.life.life;
  const expected = aliveLifeDescriptor(life);
  const current = Object.getOwnPropertyDescriptor(life, "alive");
  if (
    world.getComponent(b.actorId, COMPONENT.Alive) !== life ||
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable ||
    aliveLifeVersion(life) !== b.life.version + (life.alive ? 0 : 1)
  )
    throw new Error("order_prince_original_life_revoked");
  return b;
}
export function installOrderPrinceBoard(world: World): void {
  if (bindings.has(world)) throw new Error("order_prince_board_already_installed");
  const actors = world
    .entityIds()
    .filter((id) => own(world.getComponent(id, COMPONENT.Role), "role") === ORDER_PRINCE_ROLE);
  if (actors.length !== 1) throw new Error("order_prince_original_roster_invalid");
  const actorId = actors[0]!;
  const role = world.getComponent(actorId, COMPONENT.Role)!;
  const state = getOrderPrinceState(role);
  const life = captureNightLife(world, actorId);
  const identity = world.getComponent(actorId, COMPONENT.Identity);
  if (!state || state.history.length || !life || own(identity, "id") !== actorId)
    throw new Error("order_prince_original_roster_invalid");
  bindings.set(world, {
    actorId,
    role,
    privateState: role.privateState,
    state,
    expected: JSON.stringify(projectOrderPrinceState(role)),
    identity,
    identityValue: identityValue(identity),
    life,
    pendingDay: null,
  });
}
export function openOrderPrinceChoice(world: World, day: number): number | null {
  const b = requireAuthority(world);
  if (b.pendingDay !== null) throw new Error("order_prince_choice_reentrant");
  if (!livingNightLife(world, b.life)) return null;
  if (!nextOrderPrinceChoice(b.role, day, false)) return null;
  b.pendingDay = day;
  return b.actorId;
}
export function orderPrinceChoicePending(world: World, actorId: number, day: number): boolean {
  const b = requireAuthority(world);
  return (
    b.actorId === actorId &&
    b.pendingDay === day &&
    livingNightLife(world, b.life) &&
    !!nextOrderPrinceChoice(b.role, day, false)
  );
}
export function assertOrderPrinceCurrent(world: World, actorId: number): void {
  const b = requireAuthority(world);
  if (b.actorId !== actorId || !livingNightLife(world, b.life))
    throw new Error("order_prince_actor_stale");
}
export function commitOrderPrinceChoice(
  world: World,
  actorId: number,
  day: number,
  activate: boolean,
): void {
  if (!orderPrinceChoicePending(world, actorId, day)) throw new Error("order_prince_choice_stale");
  const b = requireAuthority(world);
  const next = nextOrderPrinceChoice(b.role, day, activate);
  if (!next) throw new Error("order_prince_choice_invalid");
  // 顺序不能合成事务：原槽先替换，随后更新绑定／证据并关闭 pending；失败不回滚已写前缀。
  (b.privateState as { orderPrince: OrderPrinceState }).orderPrince = next;
  b.state = next;
  b.expected = JSON.stringify(next);
  b.pendingDay = null;
}
export function closeOrderPrinceChoice(world: World): void {
  const b = bindings.get(world);
  if (b) b.pendingDay = null;
}

export function assertOrderPrinceOriginalCurrent(world: World): void {
  const b = requireAuthority(world);
  assertOrderPrinceCurrent(world, b.actorId);
}

/**
 * 负责完整捕获玩家可获知的身份、机制知识、已发表死亡、行动历史与能力／枪信息。
 * 输入为原请求与按原时点执行的窄查询；输出是原字段集合的脱离冻结 PlayerObservation。
 * World 仅在此游戏侧 adapter 读取，不交给策略；已知存活依发布事实计算，不替换为真实存活名单。
 * 角色和队友方法在 actor 参数之前查找；每个 World 读取保原位置，机制知识／权限仍归各原 owner。
 * 结构观察不提交行动、不克隆完整私有库存，也不提前执行自定义人设或角色展示回调；失败前缀保持。
 */
import { getWhiteWolfKingState } from "../mechanisms/roles/white_wolf_king/ports";
import { isAnimalDreamBoard } from "../mechanisms/roles/animal_dream/authority";
import {
  animalFoxKnowledge,
  animalPufferKnowledge,
  animalCatKnowledge,
  animalBeautyKnowledge,
  animalBearKnowledge,
} from "../mechanisms/roles/animal_dream/facts";
import {
  isNobleBodyBoard,
  getNobleBodyPlayerState,
} from "../mechanisms/roles/noble_secret_body/authority";
import {
  isFragrantPairBoard,
  fragrantPlayerKnowledge,
} from "../mechanisms/roles/fragrant_pair_seer/authority";
import { projectAlchemist, projectRaven } from "../mechanisms/roles/mist_raven/player_projection";
import { readModifierState } from "../mechanisms/roles/scholar_mentor/state";
import { scholarMentorStateForRole } from "../mechanisms/roles/scholar_mentor/night_frame";
import { projectTimeConsortState } from "../mechanisms/roles/time_wolf_consort/ports";
import { projectWolfSorcererState } from "../mechanisms/roles/wolf_sorcerer/ports";
import { projectTricksterState } from "../mechanisms/roles/trickster/ports";
import { projectOrderPrinceState } from "../mechanisms/roles/order_prince/state";
import { projectMagicianState } from "../mechanisms/roles/magician/ports";
import { projectRedMoonState } from "../mechanisms/roles/red_moon_apostle/ports";
import { projectNightmareShadowState } from "../mechanisms/roles/nightmare_shadow/state";
import { projectEvilKnightState } from "../mechanisms/roles/evil_knight/state";
import { projectDemonHunter } from "../mechanisms/roles/demon_hunter/authority";
import { weddingActorView, weddingBrideState } from "../mechanisms/roles/ghost_bride/authority";
import { projectLonelyGirl } from "../mechanisms/roles/lonely_girl/lifecycle";
import { projectWildChild } from "../mechanisms/roles/wild_child/lifecycle";
import { projectShapeshifterState } from "../mechanisms/roles/shapeshifter/state";
import { projectShapeshifterChoices } from "../mechanisms/roles/shapeshifter/setup";
import { projectThiefState } from "../mechanisms/roles/thief/state";
import { projectThiefChoices } from "../mechanisms/roles/thief/setup";
import { projectWallNote } from "../mechanisms/events/wall_notes/authority";
import {
  projectBearState,
  projectDreamerState,
  projectGuardState,
  projectHunterState,
  projectIdiotState,
  projectKnightState,
  projectWhiteWolfKingState,
  projectWolfBeautyState,
  projectWolfKingState,
} from "../mechanisms/roles/player_state";
import { readGravekeeperReport } from "@ai-werewolf-arena/replay-contract";
import { getBearState } from "../mechanisms/roles/bear/ports";
import { getHiddenWolfState } from "../mechanisms/roles/hidden_wolf/ports";
import { canHiddenWolfKnife } from "../mechanisms/roles/hidden_wolf/inheritance";
import {
  projectRoleInspectionState,
  projectSeerState,
  projectWitchState,
} from "../mechanisms/roles/abilities";
import {
