  expect(requests.filter((r) => r.context.stage === "order_prince_choice")).toHaveLength(1);
  expect(
    requests.filter((r) => r.context.stage === "order_prince_speech")[0]!.allowedTools,
  ).toEqual(["speak"]);
});

