    expect(Object.isFrozen(seen[0]!.ownState.orderPrince)).toBe(true);
    expect(openOrderPrinceChoice(f.world, 1)).toBe(actor);
    commitOrderPrinceChoice(f.world, actor, 1, false);
    await provider.getAction(request(actor));
